import os, json, time
import numpy as np

N = 26
SHARED_DIR = 'storage/shared/appxE_contribs'
OUT_DIR = 'storage/noesis/nmap/results'
SUMMARY_PATH = 'storage/noesis/nmap/appendix_E_summary_v2_1.json'
FREEZE_DIR = 'storage/noesis/nmap/freezes'

NOESIS_C = 'storage/noesis/latest_centers.txt'
NOESIS_R = 'storage/noesis/latest_radii.txt'
AUDIT_SLACK = 'storage/noesis/nmap/results/noesis_internal_topk_audit.json'        # Eval 826
AUDIT_KKT   = 'storage/noesis/nmap/results/noesis_internal_kkt_topk_audit.json'    # Eval 831

K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]
BOUNDARY_TOL = 2e-8

def load_snapshot():
    if os.path.exists(NOESIS_C) and os.path.exists(NOESIS_R):
        c = np.loadtxt(NOESIS_C, dtype=float).reshape(N, 2)
        r = np.loadtxt(NOESIS_R, dtype=float).reshape(N,)
        return c, r
    centers = []
    radius = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
    return np.array(centers, float), np.full(N, radius, float)

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    return x - r, 1.0 - x - r, y - r, 1.0 - y - r

def boundary_set(c, r, tol):
    s_xL, s_xR, s_yB, s_yT = slacks(c, r)
    out = set()
    for i in range(N):
        if s_xL[i] <= tol: out.add((i,'xL'))
        if s_xR[i] <= tol: out.add((i,'xR'))
        if s_yB[i] <= tol: out.add((i,'yB'))
        if s_yT[i] <= tol: out.add((i,'yT'))
    return out

def jaccard(A, B):
    if not A and not B: return 1.0
    if not A or not B: return 0.0
    inter = len(A & B); uni = len(A | B)
    return inter/uni if uni > 0 else 1.0

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

def norm_tol(t):
    if isinstance(t, (int,float)): return float(t)
    if isinstance(t, str):
        t = t.replace('−','-').strip()
        try: return float(t)
        except: return None
    return None

def get_index_map(data):
    im = data.get('index_map_to_noesis')
    if isinstance(im, list) and len(im) == 26 and all(isinstance(x,int) for x in im):
        return im
    return None

def remap_pair(p, idx_map):
    i, j = int(p[0]), int(p[1])
    if idx_map is not None:
        i, j = idx_map[i], idx_map[j]
    if i == j: return None
    if i > j: i, j = j, i
    return (i, j)

def remap_boundary_entry(e, idx_map):
    disc = int(e['disc']); side = str(e['side'])
    if idx_map is not None:
        disc = idx_map[disc]
    return (disc, side)

def load_contrib_boundary(data, idx_map):
    b = data.get('boundary', [])
    S = set()
    for e in b:
        try: S.add(remap_boundary_entry(e, idx_map))
        except: pass
    return S

def pairs_to_set(pairs, idx_map):
    S = set()
    for p in pairs:
        try:
            q = remap_pair(p, idx_map)
            if q is not None: S.add(q)
        except: pass
    return S

def load_contrib_topk(data, method_key):
    entries = []
    if 'topk' in data and isinstance(data['topk'], list):
        for ent in data['topk']:
            m = str(ent.get('method','')).lower()
            if (method_key == 'slack' and m.startswith('slack')) or \
               (method_key == 'kkt'   and m.startswith('kkt')):
                entries.append(ent)
    else:
        if method_key == 'slack':
            for key in list(data.keys()):
                if key.startswith('slack_top_k_'):
                    tol_str = key.replace('slack_top_k_','').replace('_','.')
                    entries.append({'method':'slack','tol':tol_str,'K':len(data[key]),'pairs':data[key]})
    return entries

def process_file(fname, c0, r0, slack_audit, kkt_audit):
    path = os.path.join(SHARED_DIR, fname)
    try:
        data = load_json(path)
    except Exception:
        return {'file': fname, 'error': 'json_load_failed'}
    idx_map = get_index_map(data)

    B_noe = boundary_set(c0, r0, tol=BOUNDARY_TOL)
    B_contrib = load_contrib_boundary(data, idx_map)
    boundary = {
        'tol': BOUNDARY_TOL,
        'noesis_count': len(B_noe),
        'contrib_count': len(B_contrib),
        'jaccard': jaccard(B_noe, B_contrib)
    }

    entries_slack = []
    if slack_audit:
        for ent in load_contrib_topk(data, 'slack'):
            t = norm_tol(ent.get('tol'))
            K = int(ent.get('K', len(ent.get('pairs',[]))))
            if t in TOLS and K in K_GRID:
                S_contrib = pairs_to_set(ent.get('pairs',[]), idx_map)
                try:
                    noe_list = slack_audit['topk_pairs'][str(t)][str(K)]
                except Exception:
                    noe_list = []
                S_noe = pairs_to_set(noe_list, None)
                entries_slack.append({
                    'tol': t, 'K': K,
                    'contrib_size': len(S_contrib),
                    'noesis_size': len(S_noe),
                    'jaccard': jaccard(S_noe, S_contrib)
                })

    entries_kkt = []
    if kkt_audit:
        for ent in load_contrib_topk(data, 'kkt'):
            t = norm_tol(ent.get('tol'))
            K = int(ent.get('K', len(ent.get('pairs',[]))))
            if t in TOLS and K in K_GRID:
                S_contrib = pairs_to_set(ent.get('pairs',[]), idx_map)
                try:
                    noe_list = kkt_audit['topk_pairs'][str(t)][str(K)]
                except Exception:
                    noe_list = []
                S_noe = pairs_to_set(noe_list, None)
                entries_kkt.append({
                    'tol': t, 'K': K,
                    'contrib_size': len(S_contrib),
                    'noesis_size': len(S_noe),
                    'jaccard': jaccard(S_noe, S_contrib)
                })

    res = {
        'file': fname,
        'index_map_present': (get_index_map(data) is not None),
        'boundary': boundary,
        'topk_slack': {'entries': entries_slack},
        'topk_kkt':   {'entries': entries_kkt},
    }
    return res

def construct_packing():
    c0, r0 = load_snapshot()
    os.makedirs(OUT_DIR, exist_ok=True)
    files = [f for f in os.listdir(SHARED_DIR) if f.endswith('.json')]
    # Load Noesis audits if present
    slack_audit = load_json(AUDIT_SLACK) if os.path.exists(AUDIT_SLACK) else None
    kkt_audit   = load_json(AUDIT_KKT)   if os.path.exists(AUDIT_KKT)   else None

    results = []
    for f in sorted(files):
        # skip templates
        if 'template' in f.lower() or f.endswith('_example.json'):
            continue
        # crossing-only files are handled in Gate v2 runs; include basic presence note
        if 'crossing' in f.lower():
            results.append({'file': f, 'note': 'crossings_only'})
            continue
        results.append(process_file(f, c0, r0, slack_audit, kkt_audit))

    summary = {
        'generated_at': time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime()),
        'files_seen': len(files),
        'processed': len(results),
        'k_grid': K_GRID,
        'tols': TOLS,
        'boundary_tol': BOUNDARY_TOL,
        'results': results
    }
    with open(SUMMARY_PATH, 'w') as f:
        json.dump(summary, f, indent=2)
    os.makedirs(FREEZE_DIR, exist_ok=True)
    with open(os.path.join(FREEZE_DIR, f'appendix_E_summary_v2_1_refresh_{summary["generated_at"]}.json'), 'w') as f:
        json.dump(summary, f, indent=2)

    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)

